import React, { useState } from 'react';

const colorMap = {
  blue:   { bg: '#E6F1FB', icon: '#185FA5' },
  green:  { bg: '#EAF3DE', icon: '#3B6D11' },
  amber:  { bg: '#FAEEDA', icon: '#BA7517' },
  pink:   { bg: '#FBEAF0', icon: '#993556' },
  gray:   { bg: '#F1EFE8', icon: '#5F5E5A' },
  teal:   { bg: '#E1F5EE', icon: '#0F6E56' },
  purple: { bg: '#EEEDFE', icon: '#534AB7' },
  coral:  { bg: '#FAECE7', icon: '#993C1D' },
};

export default function ProjectCard({ project }) {
  const [hovered, setHovered] = useState(false);
  const c = colorMap[project.color] || colorMap.blue;
  const isLive = project.status === 'live';

  const handleClick = () => {
    if (isLive && project.url) window.open(project.url, '_blank', 'noopener,noreferrer');
  };

  return (
    <div
      onClick={handleClick}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        background: '#fff',
        border: hovered && isLive ? '0.5px solid rgba(0,0,0,0.25)' : '0.5px solid rgba(0,0,0,0.09)',
        borderRadius: 18,
        padding: '1.4rem 1.25rem',
        display: 'flex',
        flexDirection: 'column',
        gap: 14,
        cursor: isLive ? 'pointer' : 'default',
        opacity: isLive ? 1 : 0.6,
        transform: hovered && isLive ? 'translateY(-4px)' : 'translateY(0)',
        boxShadow: hovered && isLive ? '0 10px 30px rgba(0,0,0,0.08)' : 'none',
        transition: 'transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease',
      }}
    >
      {/* Icon */}
      <div style={{
        width: 48,
        height: 48,
        borderRadius: 12,
        background: c.bg,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
      }}>
        <i className={`ti ${project.icon}`} style={{ fontSize: 24, color: c.icon }} />
      </div>

      {/* Text */}
      <div style={{ flex: 1 }}>
        <div style={{ fontWeight: 600, fontSize: 15, color: '#1a1a18', marginBottom: 5 }}>
          {project.name}
        </div>
        <div style={{ fontSize: 12, color: '#888', lineHeight: 1.5 }}>
          {project.description}
        </div>
      </div>

      {/* Status + Arrow */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12, fontWeight: 500, color: isLive ? '#3B6D11' : '#BA7517' }}>
          <span style={{
            width: 7, height: 7, borderRadius: '50%',
            background: isLive ? '#3B6D11' : '#BA7517',
            display: 'inline-block',
          }} />
          {isLive ? 'Live' : 'Coming soon'}
        </div>
        {isLive && (
          <i className="ti ti-arrow-up-right" style={{
            fontSize: 16,
            color: hovered ? c.icon : '#bbb',
            transition: 'color 0.18s',
          }} />
        )}
      </div>
    </div>
  );
}
